"""Migrated invoiced-order validation, workflow, and total recomputation rules."""

from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")
_ZERO = Decimal("0")
_HUNDRED = Decimal("100")


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context and NVL coercion."""
    if value is None:
        return _ZERO
    if isinstance(value, str) and value.strip() == "":
        return _ZERO
    return Decimal(str(value))


def _rounded_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    return row.get("DEL_FLG") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the I-to-X workflow actions."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = dict(order)

    if new_status == "I":
        return updated_order, [], []

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live-line extensions and the non-frozen order total."""
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]

    # Deleted headers are excluded from legacy reads. Invoiced and cancelled
    # orders are frozen and therefore produce no recalculation or audit.
    if _is_deleted(order) or order.get("STAT_CD") in ("I", "X"):
        return updated_order, updated_lines, []

    total = _ZERO

    for original_line, updated_line in zip(lines, updated_lines):
        if _is_deleted(original_line):
            continue

        extension = _rounded_cents(
            _numeric(original_line.get("QTY"))
            * _numeric(original_line.get("UNIT_PRC"))
        )
        updated_line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _rounded_cents(
        total * (_HUNDRED - _numeric(order.get("DISC_PCT"))) / _HUNDRED
    )

    stored_total = _numeric(order.get("TOT_AMT"))
    updated_order["TOT_AMT"] = float(discounted_total)

    if stored_total != discounted_total:
        return updated_order, updated_lines, ["ORD_RETOTAL"]

    return updated_order, updated_lines, []
